-- t41 DRY-RUN — apply 를 2회 돌려 멱등을 실증하고 rollback 까지 검증한 뒤 ROLLBACK 한다.
-- 라이브에는 아무것도 남지 않는다.

\echo '=== 0. 적용 전 상태 ==='
SELECT 'plate' AS what, ps.siz_cd AS val, count(*) AS rows
  FROM t_prd_product_plate_sizes ps
 WHERE COALESCE(ps.del_yn,'N')='N'
   AND ps.prd_cd IN ('PRD_000052','PRD_000053','PRD_000054','PRD_000058','PRD_000059',
                     'PRD_000060','PRD_000061','PRD_000062','PRD_000063','PRD_000064',
                     'PRD_000065')
 GROUP BY 2
UNION ALL
SELECT 'use_dims', use_dims::text, 1 FROM t_prc_price_components
 WHERE comp_cd='STK_KISSCUT_PRINT'
UNION ALL
SELECT 'price_rows', 'total', count(*) FROM t_prc_component_prices
 WHERE comp_cd='STK_KISSCUT_PRINT'
 ORDER BY 1, 2;

BEGIN;

\echo '=== 1. apply 1회 — UPDATE 10 / UPDATE 1 / INSERT 648 기대 ==='

-- ① 판형 교체 -------------------------------------------------------
UPDATE t_prd_product_plate_sizes
   SET siz_cd = 'SIZ_000498',
       upd_dt = now()
 WHERE prd_cd IN ('PRD_000052',
                       'PRD_000053',
                       'PRD_000054',
                       'PRD_000058',
                       'PRD_000059',
                       'PRD_000060',
                       'PRD_000061',
                       'PRD_000062',
                       'PRD_000063',
                       'PRD_000064')
   AND siz_cd = 'SIZ_000521'
   AND COALESCE(del_yn, 'N') = 'N';

-- ② use_dims -------------------------------------------------------
UPDATE t_prc_price_components
   SET use_dims = '["siz_cd", "mat_cd", "plt_siz_cd", "min_qty"]'::jsonb,
       upd_dt   = now()
 WHERE comp_cd = 'STK_KISSCUT_PRINT'
   AND use_dims = '["siz_cd", "mat_cd", "min_qty"]'::jsonb;

