       ) AS v(comp_cd, apply_ymd, siz_cd, mat_cd, min_qty, unit_price, note)
 WHERE NOT EXISTS (
       SELECT 1 FROM t_prc_component_prices p
        WHERE p.comp_cd   = v.comp_cd
          AND p.apply_ymd = v.apply_ymd
          AND p.siz_cd    = v.siz_cd
          AND p.mat_cd    = v.mat_cd
          AND p.min_qty   = v.min_qty
          AND 
p.plt_siz_cd IS NULL          AND p.clr_cd IS NULL          AND p.proc_cd IS NULL          AND p.opt_cd IS NULL          AND p.print_opt_cd IS NULL          AND p.coat_side_cnt IS NULL          AND p.spot_side_cnt IS NULL          AND p.bdl_qty IS NULL          AND p.page_cnt IS NULL          AND p.siz_width IS NULL          AND p.siz_height IS NULL          AND p.dim_vals IS NULL);

\echo '=== 3. 적용 후 상태 — 판형 498x10 + 521x1(스티커팩) · use_dims 4축 · 단가행 2592 ==='
SELECT 'plate' AS what, ps.siz_cd AS val, count(*) AS rows
  FROM t_prd_product_plate_sizes ps
 WHERE COALESCE(ps.del_yn,'N')='N'
   AND ps.prd_cd IN ('PRD_000052','PRD_000053','PRD_000054','PRD_000058','PRD_000059',
                     'PRD_000060','PRD_000061','PRD_000062','PRD_000063','PRD_000064',
                     'PRD_000065')
 GROUP BY 2
UNION ALL
SELECT 'use_dims', use_dims::text, 1 FROM t_prc_price_components
 WHERE comp_cd='STK_KISSCUT_PRINT'
UNION ALL
SELECT 'price_rows', 'total', count(*) FROM t_prc_component_prices
 WHERE comp_cd='STK_KISSCUT_PRINT'
 ORDER BY 1, 2;

\echo '=== 4. 판수 실측 — 시트 판걸이와 같아야 한다(A6 8 · A5 4 · A4 2 · 100x140 8 · 124x186 4 · 90x190 6) ==='
SELECT s.siz_nm, fn_calc_pansu('SIZ_000498', s.siz_cd) AS pansu
  FROM t_siz_sizes s
 WHERE s.siz_cd IN ('SIZ_000057','SIZ_000426','SIZ_000258','SIZ_000058',
                    'SIZ_000059','SIZ_000060','SIZ_000067')
 ORDER BY 1;

\echo '=== 5. rollback 검증 — DELETE 648 / UPDATE 1 / UPDATE 10 기대 ==='

-- ③ 단가행 648행 제거 (이 카드가 넣은 것만)
DELETE FROM t_prc_component_prices
 WHERE comp_cd = 'STK_KISSCUT_PRINT'
   AND apply_ymd = '2026-09-02'
   AND note LIKE '권위 스티커 r% c1%'
   AND ( (siz_cd = 'SIZ_000057' AND mat_cd IN ('MAT_000609','MAT_000611'))
      OR  siz_cd IN ('SIZ_000058','SIZ_000067') );

-- ② use_dims 원복
UPDATE t_prc_price_components
   SET use_dims = '["siz_cd", "mat_cd", "min_qty"]'::jsonb,
       upd_dt   = now()
 WHERE comp_cd = 'STK_KISSCUT_PRINT'
   AND use_dims = '["siz_cd", "mat_cd", "plt_siz_cd", "min_qty"]'::jsonb;

-- ① 판형 원복
UPDATE t_prd_product_plate_sizes
   SET siz_cd = 'SIZ_000521',
       upd_dt = now()
 WHERE prd_cd IN ('PRD_000052','PRD_000053','PRD_000054','PRD_000058','PRD_000059',
                  'PRD_000060','PRD_000061','PRD_000062','PRD_000063','PRD_000064')
   AND siz_cd = 'SIZ_000498'
   AND COALESCE(del_yn,'N') = 'N';

\echo '=== 6. 되돌린 뒤 상태 — 0번과 같아야 한다 ==='
SELECT 'plate' AS what, ps.siz_cd AS val, count(*) AS rows
  FROM t_prd_product_plate_sizes ps
 WHERE COALESCE(ps.del_yn,'N')='N'
   AND ps.prd_cd IN ('PRD_000052','PRD_000053','PRD_000054','PRD_000058','PRD_000059',
                     'PRD_000060','PRD_000061','PRD_000062','PRD_000063','PRD_000064',
                     'PRD_000065')
 GROUP BY 2
UNION ALL
SELECT 'use_dims', use_dims::text, 1 FROM t_prc_price_components
 WHERE comp_cd='STK_KISSCUT_PRINT'
UNION ALL
SELECT 'price_rows', 'total', count(*) FROM t_prc_component_prices
 WHERE comp_cd='STK_KISSCUT_PRINT'
 ORDER BY 1, 2;

